#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn concat(a: &[i32], b: &[i32]) -> (res: Vec<i32>)
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> res@[j + a@.len()] == b@[j],
{
    let mut res: Vec<i32> = Vec::new();

    // Push all elements of a
    let mut i: usize = 0;
    while i < a.len()
        invariant
            res@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> res@[k] == a@[k],
        decreases a.len() - i
    {
        res.push(a[i]);

        // Establish invariants for next iteration
        assert(res@.len() == i as int + 1);
        assert(forall|k: int| 0 <= k < i as int ==> res@[k] == a@[k]);

        i += 1;
    }

    // Push all elements of b
    let mut j: usize = 0;
    while j < b.len()
        invariant
            res@.len() == a@.len() + j as int,
            forall|k: int| 0 <= k < a@.len() ==> res@[k] == a@[k],
            forall|k: int| 0 <= k < j as int ==> res@[a@.len() + k] == b@[k],
        decreases b.len() - j
    {
        res.push(b[j]);

        // Establish invariants for next iteration
        assert(res@.len() == a@.len() + (j as int + 1));
        assert(forall|k: int| 0 <= k < j as int ==> res@[a@.len() + k] == b@[k]);

        j += 1;
    }

    res
}

} // verus!